setup.schemas:
import {defineSchemaRegistry,schema} from '@pulse-compute/pulse/schema';
import type {Cell,Cells,Strings,Numbers,OptionalCells,DeepCells,Matrix} from './types';
export default defineSchemaRegistry({schemas:{'probe.Cell':schema<Cell>(),'probe.Cells':schema<Cells>(),'probe.Strings':schema<Strings>(),'probe.Numbers':schema<Numbers>(),'probe.OptionalCells':schema<OptionalCells>(),'probe.DeepCells':schema<DeepCells>(),'probe.Matrix':schema<Matrix>()}});

setup.types:
export interface Cell {tag:string;text:string}
export interface Cells {items:Cell[]}
export interface Strings {items:string[]}
export interface Numbers {items:number[]}
export interface OptionalCell {tag:string;text?:string}
export interface OptionalCells {items:OptionalCell[]}
export interface DeepCell {tag:string;payload:{text:string}}
export interface DeepCells {items:DeepCell[]}
export interface Matrix {items:string[][]}

