import {Pulse} from '@pulse-compute/pulse';
import type {Cell,Cells,Strings,Numbers,OptionalCells,DeepCells,Matrix} from './types';
import {check} from './helper';
const app=new Pulse({auto:true});app.post('/probe',async(ctx)=>{const answer=check('sample');return ctx.text(answer?'yes':'no')});export default app;

